const runTests = () => {
  const scenarios = [
    { input: 'google.com', expected: 'https://google.com/' },
    { input: 'HTTP://Host.Com:80/About/', expected: 'http://host.com/About' },
    { input: '//example.com?ref=123&z=0&a=1', expected: 'https://example.com/?a=1&z=0' },
    { input: 'https://site.com/path/#hash', expected: 'https://site.com/path#hash' },
    { input: 'https://test.com/index?utm_campaign=winter&search=node', expected: 'https://test.com/index?search=node' }
  ];

  scenarios.forEach(({ input, expected }, index) => {
    const result = normalizeUrl(input);
    if (result !== expected) {
      throw new Error(`Test ${index} failed: Expected ${expected}, got ${result}`);
    }
  });

  return 'All tests passed';
};
